/* 
   1. ELIMINACION DE TABLAS EN ORDEN INVERSO DE DEPENDENCIAS */
IF OBJECT_ID('SP_RealizarVenta', 'P') IS NOT NULL DROP PROCEDURE SP_RealizarVenta;
IF TYPE_ID('dbo.TipoDetalleVenta') IS NOT NULL DROP TYPE dbo.TipoDetalleVenta;

IF OBJECT_ID('FK_Usuario_AdminRegistro', 'F') IS NOT NULL
    ALTER TABLE Usuario DROP CONSTRAINT FK_Usuario_AdminRegistro;

IF OBJECT_ID('Auditoria_Cliente', 'U')    IS NOT NULL DROP TABLE Auditoria_Cliente;
IF OBJECT_ID('Cancelacion', 'U')          IS NOT NULL DROP TABLE Cancelacion;
IF OBJECT_ID('Factura', 'U')              IS NOT NULL DROP TABLE Factura;
IF OBJECT_ID('Boleto', 'U')               IS NOT NULL DROP TABLE Boleto;
IF OBJECT_ID('Venta', 'U')                IS NOT NULL DROP TABLE Venta;
IF OBJECT_ID('Partido', 'U')              IS NOT NULL DROP TABLE Partido;
IF OBJECT_ID('Zona', 'U')                 IS NOT NULL DROP TABLE Zona;
IF OBJECT_ID('Estadio', 'U')              IS NOT NULL DROP TABLE Estadio;
IF OBJECT_ID('Telefono_Cliente', 'U')     IS NOT NULL DROP TABLE Telefono_Cliente;
IF OBJECT_ID('Cliente', 'U')              IS NOT NULL DROP TABLE Cliente;
IF OBJECT_ID('Historial_Contrasena', 'U') IS NOT NULL DROP TABLE Historial_Contrasena;
IF OBJECT_ID('Operativo', 'U')            IS NOT NULL DROP TABLE Operativo;
IF OBJECT_ID('Administrador', 'U')        IS NOT NULL DROP TABLE Administrador;
IF OBJECT_ID('Usuario', 'U')              IS NOT NULL DROP TABLE Usuario;
IF OBJECT_ID('Empresa', 'U')              IS NOT NULL DROP TABLE Empresa;
GO

--2. CREACION DE TABLAS

-- Tabla: Empresa (datos fiscales del emisor de las facturas)
CREATE TABLE Empresa (
    IdEmpresa   INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Empresa PRIMARY KEY,
    Nombre      VARCHAR(150) NOT NULL,
    RFC         VARCHAR(13)  NOT NULL
                CONSTRAINT UQ_Empresa_RFC UNIQUE
                CONSTRAINT CK_Empresa_RFC CHECK (LEN(RFC) BETWEEN 12 AND 13),
    Direccion   VARCHAR(250) NOT NULL
);

-- Tabla: Usuario 
CREATE TABLE Usuario (
    IdUsuario           INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Usuario PRIMARY KEY,
    TipoUsuario         VARCHAR(20)  NOT NULL
                        CONSTRAINT CK_Usuario_Tipo CHECK (TipoUsuario IN ('Administrador', 'Operativo')),
    EstadoUsuario       VARCHAR(20)  NOT NULL
                        CONSTRAINT DF_Usuario_Estado DEFAULT 'Activo'
                        CONSTRAINT CK_Usuario_Estado CHECK (EstadoUsuario IN ('Activo', 'Inactivo')), -- baja logica
    IdAdministradorReg  INT NULL,     -- administrador que registro al usuario
    Correo              VARCHAR(50)  NOT NULL
                        CONSTRAINT UQ_Usuario_Correo UNIQUE
                        CONSTRAINT CK_Usuario_Correo CHECK (Correo LIKE '_%@_%._%' AND Correo NOT LIKE '% %'),
    -- La intercalacion binaria hace que la contrasena distinga mayusculas de minusculas
    -- (tanto en la restriccion como al iniciar sesion).
    Contrasena          VARCHAR(255) COLLATE Latin1_General_BIN NOT NULL
                        CONSTRAINT CK_Usuario_Contrasena CHECK (
                            LEN(Contrasena) >= 8
                            AND Contrasena LIKE '%[A-Z]%'
                            AND Contrasena LIKE '%[a-z]%'
                            AND Contrasena LIKE '%[^a-zA-Z0-9]%'),
    NombreCompleto      VARCHAR(150) NOT NULL
                        CONSTRAINT CK_Usuario_Nombre CHECK (LEN(LTRIM(RTRIM(NombreCompleto))) > 0),
    NumeroNomina        VARCHAR(20)  NOT NULL CONSTRAINT UQ_Usuario_Nomina UNIQUE,
    FechaNacimiento     DATE         NOT NULL,
    FechaHoraRegistro   DATETIME     NOT NULL CONSTRAINT DF_Usuario_FechaRegistro DEFAULT GETDATE(),
    CONSTRAINT CK_Usuario_FechaNacimiento CHECK (FechaNacimiento < FechaHoraRegistro)
);

-- Tabla: Administrador (subtipo de Usuario)
CREATE TABLE Administrador (
    IdUsuario   INT NOT NULL CONSTRAINT PK_Administrador PRIMARY KEY,   -- PK y FK hacia Usuario
    ClaveAdmin  VARCHAR(50) NOT NULL CONSTRAINT UQ_Administrador_Clave UNIQUE
);

-- Tabla: Operativo (subtipo de Usuario)
CREATE TABLE Operativo (
    IdUsuario    INT NOT NULL CONSTRAINT PK_Operativo PRIMARY KEY,      -- PK y FK hacia Usuario
    CajaAsignada VARCHAR(50) NOT NULL CONSTRAINT UQ_Operativo_Caja UNIQUE
);

-- Tabla: Historial_Contrasena (atributo multivaluado de Usuario)
CREATE TABLE Historial_Contrasena (
    IdHistorial INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Historial_Contrasena PRIMARY KEY,
    IdUsuario   INT NOT NULL,
    ContrasenaH VARCHAR(255) COLLATE Latin1_General_BIN NOT NULL,
    FechaCambio DATETIME2 NOT NULL CONSTRAINT DF_Historial_Fecha DEFAULT GETDATE()
);

-- Tabla: Cliente
CREATE TABLE Cliente (
    IdCliente           INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Cliente PRIMARY KEY,
    IdUsuarioRegistro   INT NOT NULL,   -- usuario que registro al cliente
    Nombre              VARCHAR(80)  NOT NULL,
    Apellido            VARCHAR(100) NOT NULL,
    DomicilioCompleto   VARCHAR(250) NOT NULL,
    RFC                 VARCHAR(13)  NOT NULL
                        CONSTRAINT UQ_Cliente_RFC UNIQUE
                        CONSTRAINT CK_Cliente_RFC CHECK (
                            RFC LIKE '[A-Z][A-Z][A-Z][A-Z][0-9][0-9][0-9][0-9][0-9][0-9][A-Z0-9][A-Z0-9][A-Z0-9]'
                            OR RFC LIKE '[A-Z][A-Z][A-Z][0-9][0-9][0-9][0-9][0-9][0-9][A-Z0-9][A-Z0-9][A-Z0-9]'),
    Correo              VARCHAR(100) NOT NULL
                        CONSTRAINT UQ_Cliente_Correo UNIQUE
                        CONSTRAINT CK_Cliente_Correo CHECK (Correo LIKE '_%@_%._%' AND Correo NOT LIKE '% %'),
    EstadoCliente       INT NOT NULL
                        CONSTRAINT DF_Cliente_Estado DEFAULT 1
                        CONSTRAINT CK_Cliente_Estado CHECK (EstadoCliente IN (1, 0)),   -- 1 = activo, 0 = baja logica
    FechaNacimiento     DATE NOT NULL,
    FechaHoraRegistro   DATETIME NOT NULL CONSTRAINT DF_Cliente_FechaRegistro DEFAULT GETDATE(),
    CONSTRAINT CK_Cliente_FechaNacimiento CHECK (FechaNacimiento < FechaHoraRegistro)
);

-- Tabla: Telefono_Cliente (atributo multivaluado de Cliente)
CREATE TABLE Telefono_Cliente (
    IdCliente    INT NOT NULL,
    Telefono     VARCHAR(15) NOT NULL
                 CONSTRAINT CK_Telefono_Formato CHECK (LEN(Telefono) = 10 AND Telefono NOT LIKE '%[^0-9]%'),
    TipoTelefono VARCHAR(10) NOT NULL
                 CONSTRAINT CK_Telefono_Tipo CHECK (TipoTelefono IN ('Casa', 'Celular')),
    CONSTRAINT PK_Telefono_Cliente PRIMARY KEY (IdCliente, Telefono)
);

-- Tabla: Estadio (catalogo administrado por Administradores)
CREATE TABLE Estadio (
    IdEstadio           INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Estadio PRIMARY KEY,
    IdUsuarioRegistro   INT NOT NULL,   -- administrador que registro el estadio
    Nombre              VARCHAR(150) NOT NULL CONSTRAINT UQ_Estadio_Nombre UNIQUE,
    Ciudad              VARCHAR(100) NOT NULL,
    CapacidadTotal      INT NOT NULL CONSTRAINT CK_Estadio_Capacidad CHECK (CapacidadTotal > 0),
    MapaEstadio         VARBINARY(MAX) NOT NULL  -- imagen del mapa (PNG, JPG, BMP o GIF)
                        CONSTRAINT CK_Estadio_Mapa CHECK (DATALENGTH(MapaEstadio) > 0),
    FechaHoraRegistro   DATETIME NOT NULL CONSTRAINT DF_Estadio_FechaRegistro DEFAULT GETDATE()
);

-- Tabla: Zona (entidad debil de Estadio)
CREATE TABLE Zona (
    IdZona      INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Zona PRIMARY KEY,
    IdEstadio   INT NOT NULL,
    NombreZona  VARCHAR(100) NOT NULL,
    Asientos    INT NOT NULL CONSTRAINT CK_Zona_Asientos CHECK (Asientos > 0),
    PrecioBase  DECIMAL(10,2) NOT NULL CONSTRAINT CK_Zona_Precio CHECK (PrecioBase > 0.00),
    CONSTRAINT UQ_Zona_Estadio_Nombre UNIQUE (IdEstadio, NombreZona)
);

-- Tabla: Partido
CREATE TABLE Partido (
    IdPartido       INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Partido PRIMARY KEY,
    IdEstadio       INT NOT NULL,
    FechaHora       DATETIME2(0) NOT NULL,
    EquipoLocal     VARCHAR(100) NOT NULL,
    EquipoVisitante VARCHAR(100) NOT NULL,
    Estado          VARCHAR(20) NOT NULL
                    CONSTRAINT DF_Partido_Estado DEFAULT 'Programado'
                    CONSTRAINT CK_Partido_Estado CHECK (Estado IN ('Programado', 'Terminado', 'Cancelado')),
    CONSTRAINT CK_Partido_Equipos_Diferentes CHECK (EquipoLocal <> EquipoVisitante),
    CONSTRAINT UQ_Partido_Estadio_Fecha UNIQUE (IdEstadio, FechaHora)
);

-- Tabla: Venta
CREATE TABLE Venta (
    IdVenta         INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Venta PRIMARY KEY,
    IdCliente       INT NOT NULL,
    IdPartido       INT NOT NULL,
    IdUsuarioVenta  INT NOT NULL,   -- usuario que realizo la venta
    FolioCompra     UNIQUEIDENTIFIER NOT NULL
                    CONSTRAINT DF_Venta_Folio DEFAULT NEWID()
                    CONSTRAINT UQ_Venta_Folio UNIQUE,
    FechaHoraVenta  DATETIME2(0) NOT NULL CONSTRAINT DF_Venta_Fecha DEFAULT GETDATE(),
    MetodoPago      VARCHAR(10) NOT NULL
                    CONSTRAINT CK_Venta_MetodoPago CHECK (MetodoPago IN ('Credito', 'Debito', 'Efectivo')),
    Tarjeta         DECIMAL(10,2) NULL CONSTRAINT CK_Venta_Tarjeta CHECK (Tarjeta >= 0.00),    -- monto pagado con tarjeta
    Efectivo        DECIMAL(10,2) NULL CONSTRAINT CK_Venta_Efectivo CHECK (Efectivo >= 0.00),  -- monto pagado en efectivo
    Subtotal        DECIMAL(10,2) NOT NULL CONSTRAINT CK_Venta_Subtotal CHECK (Subtotal >= 0.00),
    IVA             DECIMAL(10,2) NOT NULL CONSTRAINT CK_Venta_IVA CHECK (IVA >= 0.00),
    Total           AS (Subtotal + IVA) PERSISTED,   -- atributo derivado
    Estado          VARCHAR(20) NOT NULL
                    CONSTRAINT DF_Venta_Estado DEFAULT 'Activa'
                    CONSTRAINT CK_Venta_Estado CHECK (Estado IN ('Activa', 'Cancelada')),
    -- El monto se guarda en la columna que corresponde al metodo de pago
    CONSTRAINT CK_Venta_Pago CHECK (
        (MetodoPago = 'Efectivo' AND Efectivo IS NOT NULL AND Tarjeta IS NULL)
        OR (MetodoPago IN ('Credito', 'Debito') AND Tarjeta IS NOT NULL AND Efectivo IS NULL))
);

-- Tabla: Boleto (entidad debil de Venta)
CREATE TABLE Boleto (
    IdBoleto        INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Boleto PRIMARY KEY,
    IdVenta         INT NOT NULL,
    IdZona          INT NOT NULL,
    Fila            VARCHAR(10) NOT NULL,
    NumeroAsiento   VARCHAR(10) NOT NULL,
    PrecioUnitario  DECIMAL(10,2) NOT NULL CONSTRAINT CK_Boleto_Precio CHECK (PrecioUnitario > 0.00),
    CONSTRAINT UQ_Boleto_Venta_Asiento UNIQUE (IdVenta, IdZona, Fila, NumeroAsiento)
);

-- Tabla: Factura (se genera automaticamente al realizar la venta)
CREATE TABLE Factura (
    IdFactura           INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Factura PRIMARY KEY,
    IdVenta             INT NOT NULL CONSTRAINT UQ_Factura_Venta UNIQUE,   -- relacion 1:1 con Venta
    IdEmpresa           INT NOT NULL,
    IdUsuarioEmite      INT NOT NULL,   -- usuario que realizo la venta y emitio la factura
    FolioFactura        VARCHAR(30) NOT NULL CONSTRAINT UQ_Factura_Folio UNIQUE,
    FechaHoraEmision    DATETIME2(0) NOT NULL CONSTRAINT DF_Factura_Fecha DEFAULT GETDATE(),
    NombreReceptor      VARCHAR(190) NOT NULL,
    RFCReceptor         VARCHAR(13)  NOT NULL,
    DomicilioReceptor   VARCHAR(250) NOT NULL,
    Estado              VARCHAR(20) NOT NULL
                        CONSTRAINT DF_Factura_Estado DEFAULT 'Vigente'
                        CONSTRAINT CK_Factura_Estado CHECK (Estado IN ('Vigente', 'Cancelada'))
);

-- Tabla: Cancelacion (solo la realizan Administradores)
CREATE TABLE Cancelacion (
    IdCancelacion           INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Cancelacion PRIMARY KEY,
    IdVenta                 INT NOT NULL CONSTRAINT UQ_Cancelacion_Venta UNIQUE,
    IdUsuarioAdmin          INT NOT NULL,   -- administrador que cancelo
    Motivo                  VARCHAR(250) NOT NULL
                            CONSTRAINT CK_Cancelacion_Motivo CHECK (LEN(LTRIM(RTRIM(Motivo))) > 0),
    FechaHoraCancelacion    DATETIME2(0) NOT NULL CONSTRAINT DF_Cancelacion_Fecha DEFAULT GETDATE()
);

-- Tabla: Auditoria_Cliente (relacion N:M "Modifica" entre Usuario y Cliente)
CREATE TABLE Auditoria_Cliente (
    IdAuditoria             INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Auditoria_Cliente PRIMARY KEY,
    IdCliente               INT NOT NULL,
    IdUsuarioModifica       INT NOT NULL,   -- usuario (administrador u operativo) que hizo el cambio
    FechaHoraModificacion   DATETIME2(0) NOT NULL CONSTRAINT DF_Auditoria_Fecha DEFAULT GETDATE(),
    DetalleAjuste           VARCHAR(250) NOT NULL
);
GO

--3. LLAVES FORANEAS
-- Herencia: subtipos de Usuario
ALTER TABLE Administrador ADD CONSTRAINT FK_Administrador_Usuario
    FOREIGN KEY (IdUsuario) REFERENCES Usuario(IdUsuario);

ALTER TABLE Operativo ADD CONSTRAINT FK_Operativo_Usuario
    FOREIGN KEY (IdUsuario) REFERENCES Usuario(IdUsuario);

-- Administrador que registra usuarios
ALTER TABLE Usuario ADD CONSTRAINT FK_Usuario_AdminRegistro
    FOREIGN KEY (IdAdministradorReg) REFERENCES Administrador(IdUsuario);

ALTER TABLE Historial_Contrasena ADD CONSTRAINT FK_Historial_Usuario
    FOREIGN KEY (IdUsuario) REFERENCES Usuario(IdUsuario);

ALTER TABLE Cliente ADD CONSTRAINT FK_Cliente_UsuarioRegistro
    FOREIGN KEY (IdUsuarioRegistro) REFERENCES Usuario(IdUsuario);

ALTER TABLE Telefono_Cliente ADD CONSTRAINT FK_Telefono_Cliente
    FOREIGN KEY (IdCliente) REFERENCES Cliente(IdCliente);

ALTER TABLE Estadio ADD CONSTRAINT FK_Estadio_AdminRegistro
    FOREIGN KEY (IdUsuarioRegistro) REFERENCES Administrador(IdUsuario);

ALTER TABLE Zona ADD CONSTRAINT FK_Zona_Estadio
    FOREIGN KEY (IdEstadio) REFERENCES Estadio(IdEstadio);

ALTER TABLE Partido ADD CONSTRAINT FK_Partido_Estadio
    FOREIGN KEY (IdEstadio) REFERENCES Estadio(IdEstadio);

ALTER TABLE Venta ADD CONSTRAINT FK_Venta_Cliente
    FOREIGN KEY (IdCliente) REFERENCES Cliente(IdCliente);

ALTER TABLE Venta ADD CONSTRAINT FK_Venta_Partido
    FOREIGN KEY (IdPartido) REFERENCES Partido(IdPartido);

ALTER TABLE Venta ADD CONSTRAINT FK_Venta_UsuarioVendedor
    FOREIGN KEY (IdUsuarioVenta) REFERENCES Usuario(IdUsuario);

ALTER TABLE Boleto ADD CONSTRAINT FK_Boleto_Venta
    FOREIGN KEY (IdVenta) REFERENCES Venta(IdVenta);

ALTER TABLE Boleto ADD CONSTRAINT FK_Boleto_Zona
    FOREIGN KEY (IdZona) REFERENCES Zona(IdZona);

ALTER TABLE Factura ADD CONSTRAINT FK_Factura_Venta
    FOREIGN KEY (IdVenta) REFERENCES Venta(IdVenta);

ALTER TABLE Factura ADD CONSTRAINT FK_Factura_Empresa
    FOREIGN KEY (IdEmpresa) REFERENCES Empresa(IdEmpresa);

-- La factura se genera en la venta, y la venta la puede hacer un operativo:
-- por eso la llave apunta a Usuario y no solo a Administrador.
ALTER TABLE Factura ADD CONSTRAINT FK_Factura_UsuarioEmite
    FOREIGN KEY (IdUsuarioEmite) REFERENCES Usuario(IdUsuario);

ALTER TABLE Cancelacion ADD CONSTRAINT FK_Cancelacion_Venta
    FOREIGN KEY (IdVenta) REFERENCES Venta(IdVenta);

-- Solo un Administrador puede cancelar
ALTER TABLE Cancelacion ADD CONSTRAINT FK_Cancelacion_UsuarioAdmin
    FOREIGN KEY (IdUsuarioAdmin) REFERENCES Administrador(IdUsuario);

ALTER TABLE Auditoria_Cliente ADD CONSTRAINT FK_Auditoria_Cliente
    FOREIGN KEY (IdCliente) REFERENCES Cliente(IdCliente);

-- Los operativos tambien administran clientes: la llave apunta a Usuario.
ALTER TABLE Auditoria_Cliente ADD CONSTRAINT FK_Auditoria_UsuarioModifica
    FOREIGN KEY (IdUsuarioModifica) REFERENCES Usuario(IdUsuario);
GO


   --4. INDICES (para acelerar  las busquedas y los reportes de la aplicaion)
CREATE NONCLUSTERED INDEX IX_Cliente_Apellido      ON Cliente (Apellido, Nombre);
CREATE NONCLUSTERED INDEX IX_Zona_IdEstadio        ON Zona (IdEstadio);
CREATE NONCLUSTERED INDEX IX_Partido_FechaHora     ON Partido (FechaHora, Estado);
CREATE NONCLUSTERED INDEX IX_Venta_IdCliente       ON Venta (IdCliente);
CREATE NONCLUSTERED INDEX IX_Venta_IdPartido       ON Venta (IdPartido, Estado);
CREATE NONCLUSTERED INDEX IX_Venta_FechaHoraVenta  ON Venta (FechaHoraVenta);
CREATE NONCLUSTERED INDEX IX_Boleto_IdVenta        ON Boleto (IdVenta);
CREATE NONCLUSTERED INDEX IX_Boleto_IdZona         ON Boleto (IdZona);
CREATE NONCLUSTERED INDEX IX_Historial_IdUsuario   ON Historial_Contrasena (IdUsuario, FechaCambio DESC);
CREATE NONCLUSTERED INDEX IX_Auditoria_IdCliente   ON Auditoria_Cliente (IdCliente, FechaHoraModificacion DESC);
GO

--5. TIPO DE TABLA para enviar el detalle de la venta (zona y cantidad) al procedimiento SP_RealizarVenta.*/
CREATE TYPE dbo.TipoDetalleVenta AS TABLE (
    IdZona   INT NOT NULL,
    Cantidad INT NOT NULL
);
GO

